using System.Globalization;
using System.Runtime.CompilerServices;
using Kerf.Engine.Topology;
using Kerf.Topology;
using FastAnalyzer = Kerf.Engine.Healing.Checks.Analyzer;
using FastResult = Kerf.Engine.Healing.Checks.ResultCheck;

namespace Kerf.Engine.Healing.Checks.Full;

/// <summary>
/// The comparison of unit "the check on small shapes": each check the kernel makes is made again by the check as it was
/// (the rest of this folder, generated by commit), and everything they find must be the same: the verdict and every status of
/// every sub-shape, in every context. Test-only. With <c>KERF_CHECK_COMPARE=file</c> in the environment it runs in any process
/// holding this code, and each process adds a line of counts to the file, and a line for any difference as it's found.
/// </summary>
internal static class CheckComparison
{
    private const string Variable = "KERF_CHECK_COMPARE";

    private static long s_checks;
    private static long s_invalid;
    private static long s_differences;
    private static long s_subShapes;
    private static string? s_file;

    public static long Compared => Interlocked.Read(ref s_checks);

    public static long Differences => Interlocked.Read(ref s_differences);

#pragma warning disable CA2255 // It's what it's for: from the environment, in whichever test process holds it
    [ModuleInitializer]
#pragma warning restore CA2255
    internal static void InstallFromEnvironment()
    {
        s_file = Environment.GetEnvironmentVariable(Variable);
        if (string.IsNullOrEmpty(s_file))
        {
            return;
        }

        FastAnalyzer.Finished = static (analyzer, shape, geometry) =>
        {
            string? difference = Compare(analyzer, shape, geometry);
            if (difference is not null)
            {
                Interlocked.Increment(ref s_differences);
                Append($"DIFFERENCE {shape.Type}: {difference}");
            }
        };
        AppDomain.CurrentDomain.ProcessExit += static (_, _) =>
            Append(string.Create(CultureInfo.InvariantCulture,
                                 $"process {Environment.ProcessId}: {Compared} checks, {Interlocked.Read(ref s_invalid)} invalid, {Interlocked.Read(ref s_subShapes)} sub-shapes, {Differences} differences"));
    }

    private static void Append(string line)
    {
        lock (typeof(CheckComparison))
        {
            File.AppendAllText(s_file!, line + Environment.NewLine);
        }
    }

    /// <summary>Checks the shape both ways, with the same options, and says how they differ, or null.</summary>
    public static string? Compare(in Shape shape, bool geometry = true, bool parallel = false, bool exact = false)
        => Compare(new FastAnalyzer(shape, geometry, parallel, exact), shape, geometry);

    /// <summary>What <paramref name="fast"/>, a finished check of the shape, found against the check as it was; null if nothing differs.</summary>
    public static string? Compare(FastAnalyzer fast, in Shape shape, bool geometry)
    {
        Interlocked.Increment(ref s_checks);
        Analyzer full;
        try
        {
            full = new Analyzer(shape, geometry, fast.IsParallel, fast.IsExactMethod);
        }
        catch (Exception e)
        {
            return "only the full check threw: " + e.GetType().Name;
        }

        string? thrownFast = null, thrownFull = null;
        bool validFast = false, validFull = false;
        try
        {
            validFast = fast.IsValid();
        }
        catch (Exception e)
        {
            thrownFast = e.GetType().Name;
        }

        try
        {
            validFull = full.IsValid();
        }
        catch (Exception e)
        {
            thrownFull = e.GetType().Name;
        }

        if (thrownFast != thrownFull)
        {
            return $"reading the verdict threw {thrownFast ?? "nothing"} against {thrownFull ?? "nothing"}";
        }

        if (thrownFull is not null || !validFull)
        {
            Interlocked.Increment(ref s_invalid);
        }

        if (validFast != validFull)
        {
            return $"the verdict: {validFast} against the full check's {validFull}";
        }

        (Shape Shape, FastResult? Check)[] fastResults = [.. fast.Results()];
        (Shape Shape, ResultCheck? Check)[] fullResults = [.. full.Results()];
        Interlocked.Add(ref s_subShapes, fullResults.Length);
        if (fastResults.Length != fullResults.Length)
        {
            return $"{fastResults.Length} sub-shapes against {fullResults.Length}";
        }

        for (int i = 0; i < fullResults.Length; i++)
        {
            if (!fastResults[i].Shape.IsEqual(fullResults[i].Shape))
            {
                return $"sub-shape {i} isn't the same one";
            }

            FastResult? a = fastResults[i].Check;
            ResultCheck? b = fullResults[i].Check;
            if (a is null != b is null)
            {
                return $"sub-shape {i} has a check on only one side";
            }

            if (a is null || b is null)
            {
                continue;
            }

            if (!a.Status().SequenceEqual(b.Status()))
            {
                return $"sub-shape {i} ({fullResults[i].Shape.Type}): {string.Join(",", a.Status())} against {string.Join(",", b.Status())}";
            }

            // In parallel, which context came first depends on the threads, so they're matched by shape
            int contexts = 0;
            for (b.InitContextIterator(); b.MoreShapeInContext(); b.NextShapeInContext())
            {
                contexts++;
                Shape context = b.ContextualShape();
                if (!a.IsStatusOnShape(context))
                {
                    return $"sub-shape {i} ({fullResults[i].Shape.Type}) wasn't checked in a {context.Type}";
                }

                if (!a.StatusOnShape(context).SequenceEqual(b.StatusOnShape()))
                {
                    return $"sub-shape {i} ({fullResults[i].Shape.Type}) in a {context.Type}: {string.Join(",", a.StatusOnShape(context))} against {string.Join(",", b.StatusOnShape())}";
                }
            }

            int contextsFast = 0;
            for (a.InitContextIterator(); a.MoreShapeInContext(); a.NextShapeInContext())
            {
                contextsFast++;
            }

            if (contexts != contextsFast)
            {
                return $"sub-shape {i} ({fullResults[i].Shape.Type}) in {contextsFast} contexts against {contexts}";
            }

            if (!fast.IsParallel && !ContextsInSameOrder(a, b))
            {
                return $"sub-shape {i} ({fullResults[i].Shape.Type}): its contexts in another order";
            }
        }

        return null;
    }

    private static bool ContextsInSameOrder(FastResult a, ResultCheck b)
    {
        a.InitContextIterator();
        for (b.InitContextIterator(); b.MoreShapeInContext(); b.NextShapeInContext(), a.NextShapeInContext())
        {
            if (!a.ContextualShape().IsSame(b.ContextualShape()))
            {
                return false;
            }
        }

        return true;
    }
}
